export type ConnectionMode = 'relay' | 'direct';
export interface ParticipantAudio { participantId: string; streamKey: string; muted: boolean; }
export interface RoomSnapshot { mode: ConnectionMode; joined: boolean; microphoneMuted: boolean; speakersMuted: boolean; participantCount: number; participants: ParticipantAudio[]; }

function valid(p: ParticipantAudio): ParticipantAudio {
  if (!p.participantId.trim() || !p.streamKey.trim()) throw new Error('Invalid participant');
  return { ...p };
}
function pairs(query: string): string[] {
  const text = query.startsWith('?') ? query.slice(1) : query;
  return text.split('&');
}
function queryMode(query: string): ConnectionMode | undefined {
  for (const pair of pairs(query)) {
    const parts = pair.split('=');
    if (parts.length === 2 && parts[0] === 'mode' && (parts[1] === 'relay' || parts[1] === 'direct')) return parts[1];
  }
  return undefined;
}
function autoJoin(query: string): boolean {
  return pairs(query).some(pair => pair === 'join=yes');
}
export class AudioRoomState {
  private local?: ParticipantAudio;
  private readonly remotes = new Map<string, ParticipantAudio>();
  private micMuted = false;
  private outputMuted = false;
  readonly mode: ConnectionMode;
  constructor(query: string, defaultMode: ConnectionMode, local?: ParticipantAudio) {
    this.mode = queryMode(query) ?? defaultMode;
    if (autoJoin(query)) {
      if (!local) throw new Error('Local participant required');
      this.join(local);
    }
  }
  join(local: ParticipantAudio): void {
    if (this.local) throw new Error('Already joined');
    const copy = valid(local);
    this.local = copy;
    this.micMuted = copy.muted;
  }
  leave(): void {
    this.local = undefined;
    this.remotes.clear();
    this.micMuted = false;
    this.outputMuted = false;
  }
  setMicrophoneMuted(value: boolean): void {
    if (!this.local) throw new Error('Not joined');
    this.micMuted = value;
  }
  setSpeakersMuted(value: boolean): void {
    if (!this.local) throw new Error('Not joined');
    this.outputMuted = value;
  }
  setRemote(remote: ParticipantAudio): void {
    if (!this.local) throw new Error('Not joined');
    const copy = valid(remote);
    if (copy.participantId === this.local.participantId) throw new Error('Duplicate local id');
    this.remotes.set(copy.participantId, copy);
  }
  removeRemote(id: string): boolean { return this.remotes.delete(id); }
  snapshot(): RoomSnapshot {
    const participants = this.local
      ? [{ ...this.local, muted: this.micMuted }, ...Array.from(this.remotes.values(), remote => ({ ...remote }))]
      : [];
    return {
      mode: this.mode,
      joined: this.local !== undefined,
      microphoneMuted: this.micMuted,
      speakersMuted: this.outputMuted,
      participantCount: this.remotes.size,
      participants
    };
  }
}

