import { AudioRoomState, ParticipantAudio } from './solution';

function assert(value: boolean, message: string): void { if (!value) throw new Error(message); }
function equal(actual: unknown, expected: unknown, message: string): void { if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`); }
function deepEqual(actual: unknown, expected: unknown, message: string): void { if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(`${message}: ${JSON.stringify(actual)}`); }
function throws(action: () => unknown, message: string): void { let didThrow = false; try { action(); } catch { didThrow = true; } if (!didThrow) throw new Error(message); }

const local: ParticipantAudio = { participantId: 'local', streamKey: 'local-stream', muted: false };
const room = new AudioRoomState('unknown=x&mode=direct&mode=relay', 'relay');
equal(room.snapshot().mode, 'direct', 'first recognized mode wins');
deepEqual(room.snapshot().participants, [], 'new room is absent');
equal(room.snapshot().participantCount, 0, 'absent count');

room.join(local);
local.participantId = 'changed-outside';
let snap = room.snapshot();
equal(snap.participantCount, 1, 'joined count includes local');
equal(snap.participants[0].participantId, 'local', 'join copies local');
throws(() => room.join({ participantId: 'other', streamKey: 's', muted: false }), 'joining twice must throw');

room.setRemote({ participantId: 'r1', streamKey: 'one', muted: false });
const remoteInput: ParticipantAudio = { participantId: 'r2', streamKey: 'two', muted: true };
room.setRemote(remoteInput);
remoteInput.streamKey = 'mutated';
room.setRemote({ participantId: 'r1', streamKey: 'replacement', muted: true });
snap = room.snapshot();
deepEqual(snap.participants.map(p => p.participantId), ['local', 'r1', 'r2'], 'replacement preserves insertion order');
equal(snap.participants[1].streamKey, 'replacement', 'remote replaced');
equal(snap.participants[2].streamKey, 'two', 'remote input copied');
equal(snap.participantCount, 3, 'all participants counted');

room.setMicrophoneMuted(true);
room.setSpeakersMuted(true);
snap = room.snapshot();
equal(snap.participants[0].muted, true, 'microphone mute updates local');
equal(snap.speakersMuted, true, 'speaker mute updated');
snap.participants[0].muted = false;
snap.participants.push({ participantId: 'injected', streamKey: 'x', muted: false });
equal(room.snapshot().participants[0].muted, true, 'snapshot participant is copied');
equal(room.snapshot().participantCount, 3, 'snapshot array is copied');

assert(room.removeRemote('r1'), 'known remote removed');
assert(!room.removeRemote('missing'), 'unknown remote removal is false');
throws(() => room.setRemote({ participantId: 'local', streamKey: 'x', muted: false }), 'remote cannot use local id');
throws(() => room.setRemote({ participantId: '   ', streamKey: 'x', muted: false }), 'blank remote id rejected');
throws(() => room.setRemote({ participantId: 'r3', streamKey: '   ', muted: false }), 'blank stream key rejected');

room.leave();
snap = room.snapshot();
deepEqual(snap.participants, [], 'leave clears participants');
equal(snap.participantCount, 0, 'leave clears count');
equal(snap.speakersMuted, false, 'leave clears speaker mute');
throws(() => room.setMicrophoneMuted(true), 'microphone change while absent throws');
throws(() => room.setSpeakersMuted(true), 'speaker change while absent throws');
throws(() => room.setRemote({ participantId: 'r', streamKey: 's', muted: false }), 'remote while absent throws');
throws(() => room.join({ participantId: '', streamKey: 's', muted: false }), 'blank local id rejected');
throws(() => new AudioRoomState('join=yes', 'relay'), 'automatic join requires local');

const automaticLocal: ParticipantAudio = { participantId: 'auto', streamKey: 'stream', muted: true };
const automatic = new AudioRoomState('mode=bad&join=yes&mode=direct', 'relay', automaticLocal);
automaticLocal.muted = false;
equal(automatic.snapshot().mode, 'direct', 'valid mode after malformed value is used');
equal(automatic.snapshot().participantCount, 1, 'join=yes joins');
equal(automatic.snapshot().participants[0].muted, true, 'automatic local is copied');

const undecoded = new AudioRoomState('mode%3Ddirect=x&mode=relay=extra', 'direct');
equal(undecoded.snapshot().mode, 'direct', 'encoded and malformed pairs ignored');

